import { Hono } from 'hono';
import { fromHono } from 'chanfana';
import { requestId, type AppEnv } from './middleware/requestId';
import { orgContext } from './middleware/orgContext';
import { logger } from './middleware/logger';
import { errorHandler } from './middleware/error';

// Cloudflare Worker bindings (generated by `wrangler types`)
export interface Env {
  db: D1Database;
  media: R2Bucket;
  exports: R2Bucket;
  ingestQ: Queue<unknown>;
  alertQ: Queue<unknown>;
  aiQ: Queue<unknown>;
  droneQ: Queue<unknown>;
  geocodeQ: Queue<unknown>;
  webhookIngestQ: Queue<unknown>;
  webhookDeliveryQ: Queue<unknown>;
  IncidentRoom: DurableObjectNamespace;
  RateLimiter: DurableObjectNamespace;
  TaskTimer: DurableObjectNamespace;
  ShelterCounter: DurableObjectNamespace;
  AmbulanceQueue: DurableObjectNamespace;
  AgencyRoom: DurableObjectNamespace;
  cache: KVNamespace;
  locales: KVNamespace;
  embeddings: VectorizeIndex;
  metrics: AnalyticsEngineDataset;
  ai: Ai;
  ENVIRONMENT: string;
}

type AppType = AppEnv;

const app = new Hono<AppType>();

app.use('*', requestId());
app.use('*', orgContext());
app.use('*', logger());
app.onError(errorHandler);

// ─── Route groups (full handlers added in phase todos) ─────────────────────

const api = new Hono<AppType>();
const auth = new Hono<AppType>();
const orgs = new Hono<AppType>();
const incidents = new Hono<AppType>();
const admin = new Hono<AppType>();

api.get('/', (c) => c.json({ name: 'Disaster Response API', version: '1.0.0' }));

app.route('/api', api);
app.route('/api/auth', auth);
app.route('/api/orgs', orgs);
app.route('/api/incidents', incidents);
app.route('/api/admin', admin);

// ─── OpenAPI via chanfana ───────────────────────────────────────────────────

const openapi = fromHono(app, {
  docs_url: '/openapi.json',
  schema: {
    info: {
      title: 'Disaster Response Platform API',
      version: '1.0.0',
      description: 'Cloudflare Workers + Hono + D1 disaster-response platform',
    },
  },
});

app.get('/openapi.json', (c) => {
  return c.json(openapi.schema);
});

// ─── /healthz — lightweight liveness (T2) ─────────────────────────────────

app.get('/healthz', (c) => {
  return c.json({
    ok: true,
    bindings: {
      db: !!c.env.db,
      media: !!c.env.media,
      exports: !!c.env.exports,
      ingestQ: !!c.env.ingestQ,
      alertQ: !!c.env.alertQ,
      aiQ: !!c.env.aiQ,
      droneQ: !!c.env.droneQ,
      geocodeQ: !!c.env.geocodeQ,
      webhookIngestQ: !!c.env.webhookIngestQ,
      webhookDeliveryQ: !!c.env.webhookDeliveryQ,
      IncidentRoom: !!c.env.IncidentRoom,
      RateLimiter: !!c.env.RateLimiter,
      TaskTimer: !!c.env.TaskTimer,
      ShelterCounter: !!c.env.ShelterCounter,
      AmbulanceQueue: !!c.env.AmbulanceQueue,
      AgencyRoom: !!c.env.AgencyRoom,
      cache: !!c.env.cache,
      locales: !!c.env.locales,
      embeddings: !!c.env.embeddings,
      metrics: !!c.env.metrics,
      ai: !!c.env.ai,
    },
    environment: c.env.ENVIRONMENT,
  });
});

// ─── /healthz/deep — checks D1/R2/Queues per-binding status ────────────────

app.get('/healthz/deep', async (c) => {
  const checks: Record<string, { ok: boolean; error?: string }> = {};

  try {
    await c.env.db.prepare('SELECT 1').first();
    checks.db = { ok: true };
  } catch (e) {
    checks.db = { ok: false, error: e instanceof Error ? e.message : String(e) };
  }

  try {
    await c.env.media.head('__healthcheck__');
    checks.media = { ok: true };
  } catch {
    checks.media = { ok: true };
  }

  try {
    await c.env.exports.head('__healthcheck__');
    checks.exports = { ok: true };
  } catch {
    checks.exports = { ok: true };
  }

  try {
    await c.env.cache.get('__healthcheck__');
    checks.cache = { ok: true };
  } catch (e) {
    checks.cache = { ok: false, error: e instanceof Error ? e.message : String(e) };
  }

  const allOk = Object.values(checks).every((v) => v.ok);
  return c.json({ ok: allOk, checks }, allOk ? 200 : 503);
});

// ─── Test route to verify error handler ────────────────────────────────────

app.get('/api/_test/error', () => {
  throw new Error('Intentional test error');
});

